        self._advance_apply(dst)
        self._send(
            dst,
            src,
            {
                "kind": "installSnapshotReply",
                "term": st.term,
                "result": "installed",
                "lastIncludedIndex": included_index,
                "snapshotIndex": st.snapshot_index,
                "lastLogIndex": st.last_log_index(),
