                "node": dst,
                "peer": src,
                "message": "installSnapshotReply",
                "term": msg["term"],
                "result": "delivered",
                "detail": "ignored",
            })
            return

        result = msg["result"]
        if result == "installed":
            included = msg["lastIncludedIndex"]
            if included > st.match_index[src]:
                st.match_index[src] = included
            if included + 1 > st.next_index[src]:
